const R = 4200000, obras = 630000, cons = 3570000, folha = 1050000, enc = 250000;
const lucro = 756000, insumos = 900000, iss = 0.05;
const out = [];
const chk = (label, computed, stated, tol=0.005) => {
  const ok = Math.abs(computed - stated) <= tol * Math.max(1, Math.abs(stated));
  out.push(`${ok ? "PASS" : "FAIL"}  ${label}: computed ${computed.toFixed(2)} vs stated ${stated}`);
};

// 1. Simples
const das = R*0.33 - 648000;
chk("DAS", das, 738000);
const issC = cons*0.05; chk("ISS consultoria", issC, 178500);
const simp = das + issC; chk("Simples total", simp, 916500);
chk("Simples % receita", 100*simp/R, 21.82, 0.001);
chk("DAS efetiva %", 100*das/R, 17.5714, 0.0001);
chk("DAS IRPJ 35%", 0.35*das, 258300); chk("DAS CSLL 15%", 0.15*das, 110700);
chk("DAS COFINS 16,03%", 0.1603*das, 118301.40); chk("DAS PIS 3,47%", 0.0347*das, 25608.60);
chk("DAS CPP 30,50%", 0.305*das, 225090);
chk("CPP delta 294k-225,09k", 294000-0.305*das, 68910);

// 2. Presumido
const bIRPJ = cons*0.32 + obras*0.08; chk("base IRPJ Pres", bIRPJ, 1192800);
const irpjP = 0.15*bIRPJ + 0.10*(bIRPJ-240000); chk("IRPJ Pres", irpjP, 274200);
const bCSLL = cons*0.32 + obras*0.12; chk("base CSLL Pres", bCSLL, 1218000);
const csllP = 0.09*bCSLL; chk("CSLL Pres", csllP, 109620);
chk("PIS/COFINS cum", R*0.0365, 153300);
const cpp = 0.28*folha; chk("CPP", cpp, 294000);
const pres = irpjP+csllP+R*0.0365+issC+cpp; chk("Presumido total", pres, 1009620);
chk("Pres %", 100*pres/R, 24.04, 0.001);

// 3. Real
const irpjR = 0.15*lucro + 0.10*(lucro-240000); chk("IRPJ Real", irpjR, 165000);
const csllR = 0.09*lucro; chk("CSLL Real", csllR, 68040);
chk("PIS/COFINS deb", R*0.0925, 388500); chk("creditos", insumos*0.0925, 83250);
const pisnet = R*0.0925 - insumos*0.0925; chk("PIS/COFINS liq", pisnet, 305250);
const real = irpjR+csllR+pisnet+issC+cpp; chk("Real total", real, 1010790);
chk("Real %", 100*real/R, 24.07, 0.001);
chk("Real-Presumido", real-pres, 1170);
chk("Real-Simples", real-simp, 94290);
chk("Pres-Simples", pres-simp, 93120);
chk("economia IRPJ/CSLL Real vs Pres", (irpjP+csllP)-(irpjR+csllR), 150780);
chk("diff PIS/COFINS", pisnet - R*0.0365, 151950);
chk("credito alegado 1,4mi", 1400000*0.0925, 129500); chk("superestimativa", 129500-83250, 46250);

// 4. §6-A CPP-base sensitivity
chk("Pres sem CPP", pres-cpp, 715620); chk("Real sem CPP", real-cpp, 716790);
const beBase = (simp-(pres-cpp))/0.28; chk("break-even base INSS", beBase, 717429, 0.0001);
chk("folga: (1.05M-BE)*28%", (folha-beBase)*0.28, 93120);
chk("acima do BE: 1.05M-BE", folha-beBase, 332571, 0.0002);

// 5. §6-B mix
const presMix = x => { // x = share obras
  const b1 = R*( (1-x)*0.32 + x*0.08 ), b2 = R*( (1-x)*0.32 + x*0.12 );
  return 0.15*b1+0.10*(b1-240000) + 0.09*b2 + R*0.0365 + (1-x)*R*0.05 + cpp;
};
chk("mix10 Pres", presMix(0.10), 1036500); chk("mix15 Pres", presMix(0.15), 1009620);
chk("mix20 Pres", presMix(0.20), 982740); chk("mix30 Pres", presMix(0.30), 928980);
chk("formula 1090260-537600x @10%", 1090260-537600*0.10, presMix(0.10), 0.0001);
chk("formula @30%", 1090260-537600*0.30, presMix(0.30), 0.0001);
const xCross = (1090260-simp)/537600; chk("mix crossover x", xCross, 0.323, 0.01);

// Anexo IV CPP table
for (const [x, extra, tot, folga] of [[0.10,29400,945900,63720],[0.15,44100,960600,49020],[0.20,58800,975300,34320],[0.25,73500,990000,19620],[0.30,88200,1004700,4920]]) {
  chk(`AnIV share ${(x*100).toFixed(0)}% extra`, 0.28*folha*x, extra);
  chk(`AnIV share ${(x*100).toFixed(0)}% total`, simp+extra, tot);
  chk(`AnIV share ${(x*100).toFixed(0)}% folga`, pres-(simp+extra), folga);
}
const xBE = (pres-simp)/cpp; chk("AnIV break-even share", xBE, 0.317, 0.005);
chk("AnIV break-even folha", xBE*folha, 332571, 0.0002);
chk("28% x 332571.43", 0.28*(xBE*folha), 93120);

// 6. §6-C CPP deductibility scenarios
const irCs = L => (0.15*L + 0.10*Math.max(0,L-240000)) + 0.09*L;
for (const [L, ir, cs, tot, dS] of [[712000,154000,64080,995830,79330],[462000,91500,41580,910830,-5670]]) {
  chk(`C L=${L} IRPJ`, 0.15*L+0.10*(L-240000), ir); chk(`C L=${L} CSLL`, 0.09*L, cs);
  chk(`C L=${L} total`, irCs(L)+pisnet+issC+cpp, tot); chk(`C L=${L} vs Simples`, irCs(L)+pisnet+issC+cpp-simp, dS);
}
chk("escudo max 34%x294k", 0.34*cpp, 99960);
chk("C3+15% AnIV: 960600-910830", 960600-910830, 49770);

// 7. §6-D
chk("licencas negadas +18500", real+200000*0.0925, 1029290);
chk("ISS obras +31500 Simples", simp+630000*0.05, 948000);
chk("ISS obras +31500 Presumido", pres+630000*0.05, 1041120);
chk("ISS obras +31500 Real", real+630000*0.05, 1042290);
chk("creditos extras p/ empate", (real-simp)/0.0925, 1019351, 0.0001);
const Lbe = (simp-pisnet-issC-cpp+24000)/0.34; chk("lucro break-even Real", Lbe, 478676, 0.0001);

// 8. §3 marginal / R3 crossover
chk("4,5M DAS", 4500000*0.33-648000, 837000); chk("4,5M efetiva%", 100*(4500000*0.33-648000)/4500000, 18.6, 0.01);
chk("4,8M DAS", 4800000*0.33-648000, 936000); chk("4,8M ISS", 4800000*0.85*0.05, 204000);
chk("4,8M Simples total", 4800000*0.33-648000+4800000*0.85*0.05, 1140000);
const P = r => 0.071*r-24000 + 0.0261*r + 0.0365*r + 0.0425*r + cpp;
chk("P(4.2M)", P(4200000), pres, 0.0001);
chk("P(4.8M)", P(4800000), 1115280);
chk("4,8M diff Pres-Simples", P(4800000)-1140000, -24720);
const S = r => 0.33*r-648000+0.0425*r;
chk("S(4.2M)", S(4200000), simp, 0.0001);
chk("crossover R", (cpp+24000+648000)/(0.3725-0.1761), 4674134, 0.0002);
chk("crossover variant folha=25%R", (24000+648000)/(0.3725-0.1761-0.07), 4936709, 0.001);
chk("crossover variant +44100", (cpp+24000+648000-44100)/(0.3725-0.1761), 4449593, 0.001);

// 9. R2 Fator R
chk("fatorR folha %", 100*folha/R, 25.00);
chk("28% folha alvo", 0.28*R, 1176000); chk("faltam", 0.28*R-folha, 126000);
chk("p.p. gap 28-25", 28-25, 3.0);
chk("DAS teto tolerancia", pres-issC, 831120); chk("efetiva%", 100*(pres-issC)/R, 19.79, 0.001);
chk("DAS teto c/ AnIV 15%", pres-issC-44100, 787020); chk("efetiva2%", 100*(pres-issC-44100)/R, 18.74, 0.001);

// 10. §8 Dec slice
chk("Dec media", R/12, 350000);
const dDAS = 3850000*0.33-648000; chk("3,85M DAS", dDAS, 622500);
chk("3,85M ISS", 3850000*0.85*0.05, 163625);
chk("Vértice sem Dec", dDAS+163625, 786125);
chk("economia marginal", simp-(dDAS+163625), 130375);
chk("marginal %", 100*130375/350000, 37.25);
const aIRPJ = 0.15*350000+0.10*(350000-20000); chk("(a) IRPJ", aIRPJ, 85500);
const aTot = aIRPJ+0.09*350000+0.0925*350000+0.85*350000*0.05; chk("(a) total", aTot, 164250);
chk("(a) pior em", aTot-130375, 33875);
const bIRPJ2 = 0.15*63000+0.10*(63000-20000); chk("(b) IRPJ", bIRPJ2, 13750);
const bPIS = 0.0925*350000-0.0925*75000; chk("(b) PIS/COFINS", bPIS, 25437.50);
const bTot = bIRPJ2+0.09*63000+bPIS+0.85*350000*0.05+0.28*87500; chk("(b) total", bTot, 84232.50);
chk("(b) ganho", 130375-bTot, 46142.50);
// annual-240k-threshold alternative for new company (library-only reading)
const a2 = 0.15*350000+0.10*(350000-240000)+0.09*350000+0.0925*350000+0.85*350000*0.05;
const b2 = 0.15*63000+0.09*63000+bPIS+0.85*350000*0.05+0.28*87500;
out.push(`INFO alt limite anual 240k: (a) total ${a2.toFixed(2)} (pior em ${(a2-130375).toFixed(2)}), (b) total ${b2.toFixed(2)} (ganho ${(130375-b2).toFixed(2)})`);

// 11. misc
chk("sublimite excesso %", 100*(R-3600000)/3600000, 16.67, 0.001);
chk("folga teto R$", 4800000-R, 600000); chk("folga %", 100*600000/R, 14.3, 0.01);
chk("R6 gap", R-folha-enc-1400000-lucro, 744000);
chk("encargos % folha", 100*enc/folha, 23.8, 0.01);
chk("crescimento ate crossover %", 100*(4674134/R-1), 11.3, 0.05);
chk("fator R balancete %", 100*1300000/R, 30.95);
chk("Presumido trimestral base", bIRPJ/4, 298200);
chk("Presumido IRPJ tri", 0.15*(bIRPJ/4)+0.10*(bIRPJ/4-60000), 68550);
chk("Real tri base", lucro/4, 189000);
chk("Real tri IRPJ", 0.15*(lucro/4)+0.10*(lucro/4-60000), 41250);

const fails = out.filter(l=>l.startsWith("FAIL"));
return { passes: out.filter(l=>l.startsWith("PASS")).length, fails: fails.length, fails, sample: out.slice(0,6) };

